SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  'article' AS "__typename", "_root.base"."id" AS "id", "_root.or.author"."author" AS "author", "_root.ar.root.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 2 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  'author' AS "kind", "_root.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.author.base"      ) AS "_root.or.author" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  'comment' AS "__typename", "_root.ar.root.comments.base"."id" AS "id"       ) AS "_e"      ) ) AS "comments" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.base"."id") = ("article_id"))     ) AS "_root.ar.root.comments.base"      ) AS "_root.ar.root.comments"      ) AS "_root.ar.root.comments" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
